"use client";

import * as React from "react";
import { ArrowUpRight } from "lucide-react";
import { GalleryViewer } from "./gallery-viewer";
import { GalleryPicture, type GalleryImage } from "./gallery-picture";
import { INTERACTION_FOCUS } from "./imported-ui-interaction-motion";
import { NumberRoll } from "./number-roll";

export type { GalleryImage } from "./gallery-picture";

export interface ExpandingGalleryProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onSelect"
> {
  images: GalleryImage[];
  label?: string;
  onImageChange?: (image: GalleryImage | null) => void;
}

/** An image keeps its identity from the thumbnail to the viewer and back. */
export function ExpandingGallery({
  images,
  label = "Selected work",
  onImageChange,
  className = "",
  ...props
}: ExpandingGalleryProps) {
  const [selected, setSelected] = React.useState<string | null>(null);
  const frames = React.useRef(new Map<string, HTMLDivElement>());
  const triggers = React.useRef(new Map<string, HTMLButtonElement>());
  const [openingRect, setOpeningRect] = React.useState<DOMRect | null>(null);
  const index = images.findIndex((image) => image.id === selected);
  const visible = index >= 0;

  const select = (next: number) => {
    const image = images[next];
    if (!image) return;
    if (selected === null)
      setOpeningRect(
        frames.current.get(image.id)?.getBoundingClientRect() ?? null,
      );
    setSelected(image.id);
    onImageChange?.(image);
  };
  const close = () => {
    setSelected(null);
    setOpeningRect(null);
    onImageChange?.(null);
    // Focus returns to the thumbnail of the image you were on, including after browsing.
    triggers.current.get(selected ?? "")?.focus({ preventScroll: true });
  };

  return (
    <div className={`w-full text-foreground ${className}`} {...props}>
      <div className="mb-5 flex items-baseline justify-between gap-4">
        <span className="text-[13px] font-medium">{label}</span>
        <span className="font-mono text-[10px] uppercase tracking-[0.16em] text-muted-foreground">
          <NumberRoll
            value={images.length}
            format={{ minimumIntegerDigits: 2 }}
          />{" "}
          studies
        </span>
      </div>
      <div className="grid grid-cols-2 gap-x-3 gap-y-5 sm:gap-x-4">
        {images.map((image, i) => (
          <button
            key={image.id}
            type="button"
            aria-label={`Open ${image.title}`}
            aria-haspopup="dialog"
            ref={(el) => {
              if (el) triggers.current.set(image.id, el);
              else triggers.current.delete(image.id);
            }}
            onClick={() => select(i)}
            className={`group min-w-0 cursor-zoom-in rounded-2xl text-left ${INTERACTION_FOCUS}`}
          >
            <div
              ref={(el) => {
                if (el) frames.current.set(image.id, el);
                else frames.current.delete(image.id);
              }}
              className="relative overflow-hidden rounded-2xl bg-muted"
              style={{
                aspectRatio: `${Math.max(1, image.width)} / ${Math.max(1, image.height)}`,
                visibility:
                  visible && selected === image.id ? "hidden" : undefined,
              }}
            >
              <div className="size-full transition-transform duration-500 ease-out group-hover:scale-[1.025] motion-reduce:transform-none">
                <GalleryPicture key={image.src} image={image} />
              </div>
              <span className="absolute bottom-3 right-3 flex size-7 items-center justify-center rounded-full border border-border bg-background text-foreground opacity-0 transition-opacity group-hover:opacity-100 group-focus-visible:opacity-100 [@media(hover:none)]:opacity-100">
                <ArrowUpRight className="size-3.5" aria-hidden="true" />
              </span>
            </div>
            <span className="mt-2.5 flex items-baseline justify-between gap-2 px-0.5">
              <span className="truncate text-[12px] font-medium">
                {image.title}
              </span>
              <span className="font-mono text-[10px] text-muted-foreground">
                {String(i + 1).padStart(2, "0")}
              </span>
            </span>
            {image.meta && (
              <span className="mt-0.5 block truncate px-0.5 text-[11px] text-muted-foreground">
                {image.meta}
              </span>
            )}
          </button>
        ))}
      </div>
      {visible && (
        <GalleryViewer
          images={images}
          index={index}
          label={label}
          openingRect={openingRect}
          getOrigin={(id) => frames.current.get(id)}
          onSelect={select}
          onClose={close}
        />
      )}
    </div>
  );
}

"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight, X } from "lucide-react";
import { GalleryPicture, type GalleryImage } from "./gallery-picture";
import {
  EASE_OUT,
  EASE_SETTLE,
  INTERACTION_FOCUS,
  releaseVelocity,
  samplePointer,
  useInteractionReducedMotion,
  type PointerSample,
} from "./imported-ui-interaction-motion";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

type Props = {
  images: GalleryImage[];
  index: number;
  label: string;
  openingRect: DOMRect | null;
  getOrigin: (id: string) => HTMLElement | undefined;
  onSelect: (index: number) => void;
  onClose: () => void;
};
const CONTROL = `cursor-pointer disabled:cursor-default flex size-10 shrink-0 items-center justify-center rounded-full border border-border bg-background/80 text-foreground transition-colors hover:bg-accent disabled:opacity-30 ${INTERACTION_FOCUS}`;

/**
 * Holds the page still behind the viewer without touching <html>: changing the root's overflow restyles and
 * relayouts the whole page in the frame the viewer opens, which is the stutter people feel. The viewer covers the
 * screen, so stopping wheel and touch scrolling on it is enough.
 */
function holdScroll(el: HTMLElement) {
  const stop = (event: Event) => event.preventDefault();
  el.addEventListener("wheel", stop, { passive: false });
  el.addEventListener("touchmove", stop, { passive: false });
  return () => {
    el.removeEventListener("wheel", stop);
    el.removeEventListener("touchmove", stop);
  };
}
function rectTransform(from: DOMRect, to: DOMRect) {
  return `translate(${from.left - to.left}px, ${from.top - to.top}px) scale(${from.width / Math.max(1, to.width)}, ${from.height / Math.max(1, to.height)})`;
}

function LeavingStudy({
  image,
  direction,
  from,
}: {
  image: GalleryImage;
  direction: number;
  from: number;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, transform: `translateX(${from}px)` },
        { opacity: 0, transform: `translateX(${-direction * 56}px)` },
      ],
      { duration: 280, easing: EASE_OUT, fill: "forwards" },
    );
    return () => animation.cancel();
  }, [direction, from]);
  return (
    <div
      ref={ref}
      aria-hidden="true"
      inert
      className="pointer-events-none absolute inset-0"
    >
      <GalleryPicture image={image} eager />
    </div>
  );
}

export function GalleryViewer({
  images,
  index,
  label,
  openingRect,
  getOrigin,
  onSelect,
  onClose,
}: Props) {
  const reduced = useInteractionReducedMotion();
  const dialog = React.useRef<HTMLDivElement>(null);
  const closeButton = React.useRef<HTMLButtonElement>(null);
  const picture = React.useRef<HTMLDivElement>(null);
  const content = React.useRef<HTMLDivElement>(null);
  const surface = React.useRef<HTMLDivElement>(null);
  const caption = React.useRef<HTMLDivElement>(null);
  const animations = React.useRef<Animation[]>([]);
  const closing = React.useRef(false);
  const mounted = React.useRef(false);
  const previousSize = React.useRef<{ width: number; height: number } | null>(
    null,
  );
  const first = React.useRef(true);
  const direction = React.useRef(1);
  const drag = React.useRef<{
    id: number;
    start: number;
    dx: number;
    samples: PointerSample[];
  } | null>(null);
  const id = React.useId();
  const image = images[index];
  const [ghost, setGhost] = React.useState<{
    image: GalleryImage;
    direction: number;
    from: number;
  } | null>(null);

  React.useEffect(() => {
    if (!ghost) return;
    const timer = window.setTimeout(() => setGhost(null), 300);
    return () => window.clearTimeout(timer);
  }, [ghost]);

  const cancelAnimations = () => {
    animations.current.forEach((animation) => animation.cancel());
    animations.current = [];
  };

  React.useLayoutEffect(() => {
    const el = dialog.current;
    if (!el) return;
    mounted.current = true;
    // A manual popover sits in the top layer like a modal dialog but doesn't make the page inert, which restyles
    // every element on the page twice (open and close). Modality is kept by hand: aria-modal, focus trap, Escape.
    el.showPopover();
    closeButton.current?.focus({ preventScroll: true });
    const unlock = holdScroll(el);
    return () => {
      mounted.current = false;
      cancelAnimations();
      if (el.matches(":popover-open")) el.hidePopover();
      unlock();
      first.current = true;
      closing.current = false;
    };
  }, []);

  React.useLayoutEffect(() => {
    const frame = picture.current;
    if (!frame) return;
    cancelAnimations();
    frame.style.transform = "";
    if (reduced) {
      first.current = false;
      return;
    }
    const origin = first.current
      ? openingRect
      : getOrigin(image.id)?.getBoundingClientRect();
    const target = frame.getBoundingClientRect();
    const entering = first.current;
    first.current = false;
    if (entering)
      animations.current.push(
        frame.animate(
          origin
            ? [
                {
                  transform: rectTransform(origin, target),
                  borderRadius: "16px",
                },
                { transform: "none", borderRadius: "12px" },
              ]
            : [{ opacity: 0 }, { opacity: 1 }],
          { duration: 560, easing: EASE_OUT },
        ),
      );
    else if (content.current)
      animations.current.push(
        content.current.animate(
          [
            {
              transform: `translateX(${direction.current * 40}px) scale(0.985)`,
              opacity: 0,
            },
            { transform: "none", opacity: 1 },
          ],
          { duration: 380, easing: EASE_OUT },
        ),
      );
    const size = previousSize.current;
    previousSize.current = null;
    if (
      !entering &&
      size &&
      (Math.abs(size.width - target.width) > 0.5 ||
        Math.abs(size.height - target.height) > 0.5)
    ) {
      animations.current.push(
        frame.animate(
          [
            { width: `${size.width}px`, height: `${size.height}px` },
            { width: `${target.width}px`, height: `${target.height}px` },
          ],
          { duration: 380, easing: EASE_OUT },
        ),
      );
    }
    if (entering && surface.current)
      animations.current.push(
        surface.current.animate([{ opacity: 0 }, { opacity: 1 }], {
          duration: 320,
          easing: "ease-out",
        }),
      );
    if (caption.current)
      animations.current.push(
        caption.current.animate(
          [
            { opacity: 0, transform: "translateY(8px)" },
            { opacity: 1, transform: "none" },
          ],
          {
            duration: 320,
            delay: entering ? 180 : 60,
            fill: "backwards",
            easing: EASE_OUT,
          },
        ),
      );
    return cancelAnimations;
    // Geometry is sampled on selection; a resize simply reflows the settled viewer.
  }, [image.id, reduced]);

  const navigate = (next: number) => {
    if (closing.current || next < 0 || next >= images.length || next === index)
      return;
    direction.current = Math.sign(next - index);
    const rect = picture.current?.getBoundingClientRect();
    previousSize.current = rect
      ? { width: rect.width, height: rect.height }
      : null;
    if (!reduced)
      setGhost({
        image,
        direction: direction.current,
        from: (drag.current?.dx ?? 0) * 0.65,
      });
    drag.current = null;
    onSelect(next);
  };

  const close = async () => {
    if (closing.current) return;
    closing.current = true;
    const frame = picture.current;
    const current = frame?.getBoundingClientRect();
    cancelAnimations();
    const finish = () => {
      if (mounted.current && closing.current) {
        closing.current = false;
        if (dialog.current?.matches(":popover-open"))
          dialog.current.hidePopover();
        onClose();
      }
    };
    if (reduced || !frame || !current) {
      finish();
      return;
    }
    frame.style.transform = "";
    const base = frame.getBoundingClientRect();
    const target = getOrigin(image.id)?.getBoundingClientRect();
    const inView =
      target && target.bottom > 0 && target.top < window.innerHeight;
    const animation = frame.animate(
      [
        {
          transform: rectTransform(current, base),
          opacity: 1,
          borderRadius: "12px",
        },
        {
          transform: inView ? rectTransform(target, base) : "scale(0.96)",
          opacity: inView ? 1 : 0,
          borderRadius: "16px",
        },
      ],
      { duration: 380, easing: EASE_OUT, fill: "forwards" },
    );
    animations.current.push(animation);
    if (surface.current)
      animations.current.push(
        surface.current.animate([{ opacity: 1 }, { opacity: 0 }], {
          duration: 320,
          fill: "forwards",
        }),
      );
    if (caption.current)
      animations.current.push(
        caption.current.animate([{ opacity: 1 }, { opacity: 0 }], {
          duration: 100,
          fill: "forwards",
        }),
      );
    try {
      await animation.finished;
      finish();
    } catch {
      finish();
    }
  };

  const finishDrag = (event: React.PointerEvent, cancelled = false) => {
    const state = drag.current;
    if (!state || state.id !== event.pointerId) return;
    const velocity = releaseVelocity(state.samples, event.timeStamp);
    const next = index + (state.dx < 0 ? 1 : -1);
    if (
      !cancelled &&
      (Math.abs(state.dx) > 64 ||
        (Math.abs(state.dx) > 12 && Math.abs(velocity) > 0.5)) &&
      next >= 0 &&
      next < images.length
    )
      navigate(next);
    else if (picture.current) {
      const frame = picture.current;
      const from = frame.style.transform || "none";
      frame.style.transform = "";
      if (!reduced)
        animations.current.push(
          frame.animate([{ transform: from }, { transform: "none" }], {
            duration: 360,
            easing: EASE_SETTLE,
          }),
        );
    }
    drag.current = null;
  };

  return (
    <div
      ref={dialog}
      popover="manual"
      role="dialog"
      aria-modal="true"
      aria-labelledby={`${id}-title`}
      aria-describedby={`${id}-description`}
      data-lenis-prevent
      onKeyDown={(event) => {
        if (event.key === "Escape") {
          event.preventDefault();
          void close();
          return;
        }
        if (event.key === "Tab") {
          // Keep focus inside the viewer, as a modal dialog would.
          const focusable = [
            ...event.currentTarget.querySelectorAll<HTMLElement>(
              'button:not([disabled]), [href], [tabindex]:not([tabindex="-1"])',
            ),
          ];
          const first = focusable[0],
            last = focusable[focusable.length - 1];
          if (
            first &&
            last &&
            (event.shiftKey
              ? document.activeElement === first
              : document.activeElement === last)
          ) {
            event.preventDefault();
            (event.shiftKey ? last : first).focus();
          }
          return;
        }
        if (event.key === "PageUp" || event.key === "PageDown")
          event.preventDefault();
        if (
          event.key === "ArrowLeft" ||
          event.key === "ArrowRight" ||
          event.key === "Home" ||
          event.key === "End"
        ) {
          event.preventDefault();
          navigate(
            event.key === "Home"
              ? 0
              : event.key === "End"
                ? images.length - 1
                : index + (event.key === "ArrowRight" ? 1 : -1),
          );
        }
      }}
      className="fixed inset-0 m-0 h-dvh max-h-none w-screen max-w-none overflow-hidden border-0 bg-transparent p-0 text-foreground backdrop:bg-transparent"
    >
      <div
        ref={surface}
        className="absolute inset-0 cursor-zoom-out bg-background"
        onClick={() => void close()}
      />
      <div className="pointer-events-none relative flex h-full flex-col items-center justify-center gap-5 px-4 pb-5 pt-20 sm:gap-6">
        <div className="pointer-events-auto absolute inset-x-5 top-5 flex items-center justify-between sm:inset-x-8">
          <span className="text-xs font-medium tracking-wide">{label}</span>
          <button
            ref={closeButton}
            type="button"
            aria-label="Close gallery"
            onClick={() => void close()}
            className={CONTROL}
          >
            <X className="size-4" aria-hidden="true" />
          </button>
        </div>
        <div
          ref={picture}
          className="pointer-events-auto relative shrink-0 origin-top-left cursor-grab overflow-hidden rounded-xl bg-muted will-change-transform active:cursor-grabbing"
          style={{
            aspectRatio: `${Math.max(1, image.width)} / ${Math.max(1, image.height)}`,
            width: `min(88vw, calc((100dvh - 260px) * ${Math.max(1, image.width) / Math.max(1, image.height)}), 980px)`,
            touchAction: "pan-y",
          }}
          onPointerDown={(event) => {
            if (closing.current || event.button !== 0 || !event.isPrimary)
              return;
            cancelAnimations();
            event.currentTarget.setPointerCapture(event.pointerId);
            drag.current = {
              id: event.pointerId,
              start: event.clientX,
              dx: 0,
              samples: [{ x: event.clientX, time: event.timeStamp }],
            };
          }}
          onPointerMove={(event) => {
            const state = drag.current;
            if (!state || state.id !== event.pointerId) return;
            state.dx = event.clientX - state.start;
            samplePointer(state.samples, event.clientX, event.timeStamp);
            const edge =
              (index === 0 && state.dx > 0) ||
              (index === images.length - 1 && state.dx < 0);
            if (!reduced)
              event.currentTarget.style.transform = `translateX(${state.dx * (edge ? 0.18 : 0.65)}px)`;
          }}
          onPointerUp={(event) => finishDrag(event)}
          onPointerCancel={(event) => finishDrag(event, true)}
          onLostPointerCapture={(event) => finishDrag(event, true)}
        >
          {ghost && !reduced && (
            <LeavingStudy
              key={ghost.image.id}
              image={ghost.image}
              direction={ghost.direction}
              from={ghost.from}
            />
          )}
          <div ref={content} className="relative size-full">
            <GalleryPicture key={image.src} image={image} eager />
          </div>
        </div>
        <div
          ref={caption}
          className="pointer-events-auto w-full max-w-[720px] px-2"
        >
          <div className="flex items-start justify-between gap-5">
            <div className="min-w-0">
              <h2
                id={`${id}-title`}
                className="text-lg font-medium tracking-[-0.025em] sm:text-2xl"
              >
                <TextMorph animateWidth={false}>{image.title}</TextMorph>
              </h2>
              <p
                id={`${id}-description`}
                className="mt-1 line-clamp-2 max-w-[500px] text-[12px] leading-relaxed text-muted-foreground sm:text-sm"
              >
                <TextMorph animateWidth={false}>
                  {image.description ?? image.alt}
                </TextMorph>
              </p>
            </div>
            <div className="flex shrink-0 items-center gap-2">
              <button
                type="button"
                aria-label="Previous image"
                disabled={index === 0}
                onClick={() => navigate(index - 1)}
                className={CONTROL}
              >
                <ChevronLeft className="size-4" aria-hidden="true" />
              </button>
              <button
                type="button"
                aria-label="Next image"
                disabled={index === images.length - 1}
                onClick={() => navigate(index + 1)}
                className={CONTROL}
              >
                <ChevronRight className="size-4" aria-hidden="true" />
              </button>
            </div>
          </div>
          <p
            aria-live="polite"
            aria-atomic="true"
            className="mt-4 font-mono text-[10px] uppercase tracking-[0.16em] text-muted-foreground"
          >
            <NumberRoll
              value={index + 1}
              format={{ minimumIntegerDigits: 2 }}
            />{" "}
            /{" "}
            <NumberRoll
              value={images.length}
              format={{ minimumIntegerDigits: 2 }}
            />
            {image.meta && (
              <span>
                {" "}
                · <TextMorph>{image.meta}</TextMorph>
              </span>
            )}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { ImageOff } from "lucide-react";

export interface GalleryImage {
  id: string;
  src: string;
  alt: string;
  title: string;
  description?: string;
  /** Intrinsic dimensions keep the thumbnail and expanded image in the same proportions. */
  width: number;
  height: number;
  meta?: string;
}

export function GalleryPicture({
  image,
  eager = false,
}: {
  image: GalleryImage;
  eager?: boolean;
}) {
  const [failed, setFailed] = React.useState(false);
  return failed ? (
    <div
      role="img"
      aria-label={`${image.alt} (image unavailable)`}
      className="flex size-full flex-col items-center justify-center gap-2 bg-muted text-muted-foreground"
    >
      <ImageOff className="size-6" aria-hidden="true" />
      <span className="text-xs">Image unavailable</span>
    </div>
  ) : (
    <img
      src={image.src}
      alt={image.alt}
      width={image.width}
      height={image.height}
      loading={eager ? "eager" : "lazy"}
      decoding="async"
      draggable={false}
      onError={() => setFailed(true)}
      className="size-full object-cover"
    />
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

